 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    # Identify each straight diagonal stroke as a same-color adjacent pair.
    # Extend each pair in both directions, stopping at existing non-background cells.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color):
                    continue
                # Start from this pair's first cell, walk backward and forward.
                for sign in (-1, 1):
                    y, x = (r, c) if sign == -1 else (rr, cc)
                    while True:
                        y += sign * dr
                        x += sign * dc
                        if not (0 <= y < h and 0 <= x < w):
                            break
                        if out[y][x] != bg:
                            break
                        out[y][x] = color
    return out


