    out = [row[:] for row in grid]
    # Each repeated diagonal color is extended along its diagonal to the edges.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run = [(r,c)]
                rr, cc = r+dr, c+dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr,cc))
                    rr += dr
