                if len(run) < 2:
                    continue
                # Extend from the first original cell toward the preceding edge.
                rr, cc = r-dr, c-dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr -= dr
                    cc -= dc
                # Extend from the last original cell toward the following edge.
                rr, cc = run[-1][0]+dr, run[-1][1]+dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out

