    out = [row[:] for row in grid]
    # For each color, extend a diagonal run of two or more cells in its ray direction.
    for dr, dc in ((1,1),(1,-1)):
        for r in range(h):
            for c in range(w):
                color=grid[r][c]
                if color==bg: continue
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and grid[nr][nc]==color:
                    # Explore both ends from the initial pair; original color and other marks stop.
                    er,ec=nr,nc
                    while 0<=er+dr<h and 0<=ec+dc<w and grid[er+dr][ec+dc]==color:
