 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    # Extend every contiguous diagonal segment of a repeated color both ways.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run = [(r,c)]
                rr, cc = r+dr, c+dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr,cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                # extend backward from run start
                rr, cc = r-dr, c-dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr -= dr
                    cc -= dc
                # extend forward from run end
                rr, cc = run[-1][0]+dr, run[-1][1]+dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out

