 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    # Repeat-color diagonal runs are rays: complete each full line.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                col = grid[r][c]
                if col == bg:
                    continue
                # Find start of contiguous diagonal run.
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == col:
                    continue
                run = [(r,c)]
                rr, cc = r+dr, c+dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == col:
                    run.append((rr,cc)); rr += dr; cc += dc
                if len(run) < 2:
                    continue
                # Fill both extensions, unless blocked by a different color.
                for step, rr, cc in ((-1, r-dr, c-dc), (1, run[-1][0]+dr, run[-1][1]+dc)):
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = col
                        rr += step*dr; cc += step*dc
    return out
