    # extend their collinear rays to the boundaries.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for color in set(v for row in grid for v in row if v != 5):
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr, dc in ((1,1),(1,-1)):
            buckets = {}
            for r,c in pts:
                buckets.setdefault(r*dc-c*dr, []).append((r,c))
            for line in buckets.values():
                if len(line) < 2: continue
                r,c = line[0]
                while 0 <= r-dr < h and 0 <= c-dc < w:
                    r -= dr; c -= dc
                while 0 <= r < h and 0 <= c < w:
                    if out[r][c] == 5:
                        out[r][c] = color
                    r += dr; c += dc
    return out

