 "content": "def transform(grid):
    """Extend established, contiguous diagonal runs of nonzero colors.

    A diagonal pair (or longer run) is continued outward through background
    cells until the grid edge or an existing non-background cell. Zero marks
    are not extended (as in the demonstrations).
    """
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Find each maximal original run once in each diagonal orientation.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == background or color == 0:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = [(r, c)]
                rr, cc = r + dr, c + dc
                while (0 <= rr < h and 0 <= cc < w
                       and grid[rr][cc] == color):
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                # Extend backward from the start and forward from the end;
                # other marks are blockers and are preserved.
                for rr, cc, step in (
                    (r - dr, c - dc, -1),
                    (run[-1][0] + dr, run[-1][1] + dc, 1),
                ):
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] != background:
                            break
                        out[rr][cc] = color
                        rr += step * dr
                        cc += step * dc
    return out


