    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Extend diagonal runs of two or more matching non-background cells.
    # Diagonal direction is inferred from aligned repetitions; unrelated
    # singleton marks remain unchanged. Existing marks stop the extension.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == background:
                    continue
                pr, pc = r - dr, c - dc
