                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                for rr, cc, step in ((r - dr, c - dc, -1),
                                     (run[-1][0] + dr, run[-1][1] + dc, 1)):
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] != background:
